SELECT  FROM `order`

    is_deleted = 0 AND user_id = #{userId}
    AND status = #{status}

ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM `order`

    is_deleted = 0 AND user_id = #{userId}
    AND status = #{status}

SELECT  FROM `order`

    is_deleted = 0
    AND order_no LIKE CONCAT('%',#{orderNo},'%')
    AND status = #{status}

ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT  FROM `order`
WHERE is_deleted = 0
ORDER BY create_time DESC LIMIT #{limit}
